import React from 'react';
import { Link } from 'react-router-dom';
import { API_BASE_URL } from '../config/apiConfig';
import { PhotoIcon } from '@heroicons/react/24/outline';

const PhoneCard = ({ phone }) => {
  const imageUrl = phone.images && phone.images.length > 0 ? `${API_BASE_URL}${phone.images[0]}` : null;

  return (
    <Link to={`/phone/${phone._id}`} className="group block">
      <div className="w-full aspect-w-1 aspect-h-1 bg-gray-100 rounded-lg overflow-hidden">
        {imageUrl ? (
          <img
            src={imageUrl}
            alt={phone.title}
            className="w-full h-full object-center object-cover group-hover:opacity-75 transition-opacity"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center">
            <PhotoIcon className="w-16 h-16 text-gray-400" />
          </div>
        )}
      </div>
      <div className="mt-4 text-center">
        <h3 className="text-sm font-medium text-gray-900">
          {phone.title}
        </h3>
        <p className="mt-1 text-sm text-gray-500">{phone.brand}</p>
        <p className="mt-1 text-base font-semibold text-gray-900">
          ¥{phone.price}
        </p>
      </div>
    </Link>
  );
};

export default PhoneCard;
